function updateFPS() {
    const currentTime = performance.now();
    frameCount++;
    const timeElapsed = currentTime - lastFrameTime;

    if (timeElapsed >= 1000) {
        const fps = Math.round((frameCount / timeElapsed) * 1000);
        document.getElementById('fps').textContent = fps + ' FPS';
        frameCount = 0;
        lastFrameTime = currentTime;
    }
}

